-- Sons of Pitches FC, moved from the Claude-hosted app. Follow code QEZ62K.
-- The real organiser code is not stored in this public repo; get it from the app's Options screen.
with t as (insert into public.teams (code, organiser_code, name, short, color, crest, settings, created_by) values ('QEZ62K', 'REDACTEDXX', 'Sons of Pitches FC', 'SOP FC', '#4c2bb0', 'data:image/png;base64,', '{"half": 15, "sub": 5, "pitch": 5, "tactic": 100, "lastKeeper": 1, "nextId": 12}'::jsonb, null) returning id)
insert into public.players (team_id, pid, name) select t.id, v.pid, v.name from t, (values (1, 'Spice'), (2, 'Jake'), (3, 'Chaplin'), (4, 'Harrison'), (5, 'Puxley'), (6, 'Issac'), (7, 'Reece'), (8, 'Ethan'), (9, 'Ali'), (10, 'Adrian'), (11, 'Mark')) as v(pid, name);
